ProgramUnit.ProgramUnitText:
PROCEDURE APPLY_PIECE_RULES IS
BEGIN
SET_BLOCK_PROPERTY('PIECES',INSERT_ALLOWED,PROPERTY_TRUE);
SET_BLOCK_PROPERTY('PIECES',UPDATE_ALLOWED,PROPERTY_TRUE);
IF :LOADS.CLOSED_FLAG IS NOT NULL AND :LOADS.CLOSED_FLAG = 'Y' THEN
SET_BLOCK_PROPERTY('PIECES',INSERT_ALLOWED,PROPERTY_FALSE);
SET_BLOCK_PROPERTY('PIECES',UPDATE_ALLOWED,PROPERTY_FALSE);
END IF;
END;
